def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                req = opp.get('water_requirement', WATER_REQ)
                if req <= supply:
                    dangerous_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 20.0))

    affordable_supply_units = int(supply // WATER_REQ)
    scarcity = 1.0
    if affordable_supply_units <= 1:
        scarcity = 1.35
    elif supply <= 17:
        scarcity = 1.2
    elif supply >= 23:
        scarcity = 0.8
    elif supply >= 20:
        scarcity = 0.9

    urgency = 1.0
    if hp <= 2 or no_water_days >= 2:
        urgency = 1.8
    elif hp <= 4 or no_water_days >= 1:
        urgency = 1.35
    elif hp >= 8 and no_water_days == 0:
        urgency = 0.9

    pressure_bid = 0.0
    if dangerous_bids:
        pressure_bid = max(dangerous_bids)
    elif prev_bids:
        pressure_bid = max(prev_bids)

    if pressure_bid >= 90:
        target = 52.0 if urgency < 1.5 else 86.0
    elif pressure_bid >= 75:
        target = pressure_bid + 2.0
    elif pressure_bid >= 55:
        target = pressure_bid + 1.5
    elif pressure_bid > 0:
        target = max(38.0, pressure_bid + 1.0)
    else:
        target = 42.0

    target *= scarcity
    target *= urgency

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        target *= 0.7
    if supply <= 16:
        target += 8.0
    if day >= 8 and hp <= 5:
        target += 10.0

    max_safe = budget
    if hp > 5 and no_water_days == 0:
        max_safe = min(max_safe, DAILY_SALARY * 0.85)
    else:
        max_safe = min(max_safe, DAILY_SALARY * 1.05)

    bid = min(max_safe, target)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    available_units = int(current_supply // WATER_REQ)
    if available_units == 0:
        return min(my_status['budget'], 1.0)

    base_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.75

    if current_day >= EPISODE_DAYS - 2:
        if my_status['hp'] >= 5 and my_status['budget'] > DAILY_SALARY * 5:
            base_bid = max(base_bid, DAILY_SALARY * 0.85)
        elif my_status['hp'] < 5:
            base_bid = max(base_bid, DAILY_SALARY * 0.98)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 2.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + 1.0)
        else:
            base_bid = max(base_bid, highest_prev_bid + 0.5)

    potential_bidders = num_alive_opponents + 1

    if available_units < potential_bidders:
        scarce_factor = (potential_bidders / available_units) if available_units > 0 else 10.0
        base_bid *= min(scarce_factor * 0.1 + 1, 1.3)
    elif available_units > potential_bidders * 1.5:
        base_bid *= 0.95

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(1.0, final_bid)

    return final_bid
